import org.junit.jupiter.params.provider.ValueSource;

/** Compaction must not retain cumulative intermediate model copies. */
class ModelCompressionRetentionTest {
	@ParameterizedTest
	@ValueSource(ints = { 4, 16, 64 })
	void compressionKeepsLinearLiveModelEntries(int n) {
		Factory factory = new Factory();
		var vf = SimpleValueFactory.getInstance();
		Set<Statement> expected = new HashSet<>();
		SailSource backing = new BackingSailSource() {
			@Override
			public SailDataset dataset(IsolationLevel level) {
				throw new AssertionError("This compression fixture must not open a backing dataset");
			}

			@Override
			public SailSink sink(IsolationLevel level) {
				throw new AssertionError("This compression fixture must not publish to backing storage");
			}
		};
		try (var branch = new SailSourceBranch(backing, factory, false)) {
			try (SailSink observer = branch.sink(IsolationLevels.SERIALIZABLE)) {
				observer.observe(null, vf.createIRI("urn:retention:unrelated"), null, new Resource[0]);
				for (int i = 0; i < n; i++) {
					Statement st = vf.createStatement(vf.createIRI("urn:retention:s:" + i),
							vf.createIRI("urn:retention:p"), vf.createLiteral(i));
					expected.add(st);
					try (SailSink writer = branch.sink(IsolationLevels.NONE)) {
						writer.approve(st);
						writer.flush();
					}
				}
				assertEquals(n, factory.models.size(), "history retains all distinct original models");
				assertEquals(n, factory.liveEntries());
				assertEquals(0, factory.closeCalls);
			}
			branch.compressChanges();
			System.out.println("COMPRESSION entries=" + n + " peakLiveEntries=" + factory.peak
					+ " remainingLiveEntries=" + factory.liveEntries() + " closes=" + factory.closeCalls);
			assertEquals(n - 1, factory.closeCalls);
			List<TrackedModel> live = factory.models.stream().filter(m -> !m.closed).toList();
			assertEquals(1, live.size());
			assertEquals(expected, new HashSet<>(live.getFirst()));
			assertTrue(factory.peak <= 2 * n,
					"compression must not retain cumulative intermediate copies: peak=" + factory.peak);
		}
		assertEquals(n, factory.closeCalls);
	}

	private static final class Factory implements ModelFactory {
		final List<TrackedModel> models = new ArrayList<>();
		int peak;
		int closeCalls;

		@Override
		public Model createEmptyModel() {
			TrackedModel model = new TrackedModel(this);
			models.add(model);
			return model;
		}

		int liveEntries() {
			return models.stream().filter(m -> !m.closed).mapToInt(Model::size).sum();
		}

		void record() {
			peak = Math.max(peak, liveEntries());
		}
	}

	private static final class TrackedModel extends LinkedHashModel implements AutoCloseable {
		final Factory factory;
		boolean closed;

		TrackedModel(Factory factory) {
			this.factory = factory;
		}

		@Override
		public boolean add(Statement statement) {
			boolean changed = super.add(statement);
			factory.record();
			return changed;
		}

		@Override
		public boolean add(Resource s, IRI p, Value o, Resource... c) {
			boolean changed = super.add(s, p, o, c);
			factory.record();
			return changed;
		}

		@Override
		public void close() {
			assertFalse(closed, "model closed twice");
			closed = true;
			factory.closeCalls++;
			clear();
		}
	}
}
